model_features <- c("segment", "status", "state", "days_response", "days_resolution", "rating")

validate_features <- function(d) {
  missing <- setdiff(model_features, names(d))
  if (length(missing)) stop(paste("Model requires:", paste(missing, collapse = ", ")), call. = FALSE)
  invisible(TRUE)
}

load_model_bundle <- function(path = "models/model.rds") {
  if (!file.exists(path)) return(NULL)
  # Only a server-side artifact generated by scripts/train.R; never accept uploaded RDS.
  bundle <- readRDS(path)
  if (!identical(bundle$schema_version, 1L) || !identical(bundle$features, model_features))
    stop("Incompatible model artifact. Retrain with scripts/train.R.", call. = FALSE)
  if (!requireNamespace("workflows", quietly = TRUE))
    stop("Install training dependencies before loading this model.", call. = FALSE)
  if (identical(bundle$algorithm, "XGBoost") && !requireNamespace("xgboost", quietly = TRUE))
    stop("The installed model requires the xgboost package.", call. = FALSE)
  bundle
}

score_data <- function(bundle, d) {
  validate_features(d)
  probs <- predict(bundle$workflow, new_data = d, type = "prob")
  classes <- predict(bundle$workflow, new_data = d, type = "class")
  # Always report P(Yes), not the maximum probability of either class.
  data.frame(row = seq_len(nrow(d)), prediction = as.character(classes$.pred_class),
    probability_return = probs$.pred_Yes)
}
